import { getHostEndpoint } from './_endpoint';
/**
 * Copies text to the user's clipboard within the Stripe Dashboard.
 *
 * @param text - The string to write to the clipboard. Defaults to an empty string.
 * @returns A promise that resolves when the text has been written.
 * @public
 */
export const clipboardWriteText = (text = '') => {
    return getHostEndpoint().call.clipboardWriteText(text);
};
